using MetaheuristicsPlatform.Parameters;
namespace MetaheuristicsPlatform.Algorithms.Constraints.EnsembleConstraintHandling;
public sealed class EnsembleConstraintHandlingParameters : IMetaheuristicParameters
{ public int PolicyCount { get; init; }=4; public int SubpopulationSize { get; init; }=24; public int MaximumGenerations { get; init; }=160; public int ExchangePeriod { get; init; }=10; public double DifferentialWeight { get; init; }=0.5; public double CrossoverProbability { get; init; }=0.9; public double StaticPenalty { get; init; }=100.0; public double InitialEpsilon { get; init; }=1.0; public void Validate(){if(PolicyCount<4)throw new ArgumentOutOfRangeException(nameof(PolicyCount));if(SubpopulationSize<4)throw new ArgumentOutOfRangeException(nameof(SubpopulationSize));if(MaximumGenerations<=0)throw new ArgumentOutOfRangeException(nameof(MaximumGenerations));if(ExchangePeriod<=0)throw new ArgumentOutOfRangeException(nameof(ExchangePeriod));if(!double.IsFinite(DifferentialWeight)||DifferentialWeight<=0.0)throw new ArgumentOutOfRangeException(nameof(DifferentialWeight));if(!double.IsFinite(CrossoverProbability)||CrossoverProbability<0.0||CrossoverProbability>1.0)throw new ArgumentOutOfRangeException(nameof(CrossoverProbability));if(!double.IsFinite(StaticPenalty)||StaticPenalty<=0.0)throw new ArgumentOutOfRangeException(nameof(StaticPenalty));if(!double.IsFinite(InitialEpsilon)||InitialEpsilon<0.0)throw new ArgumentOutOfRangeException(nameof(InitialEpsilon));} }
